function go(view){state.activeView=view;$$('.view').forEach(v=>v.classList.remove('active'));$('#view-'+view).classList.add('active');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#screenTitle').textContent={home:'Overview',market:'Street Market',network:'Your Network',assets:'Properties & Gear',ledger:'Life Ledger'}[view];window.scrollTo({top:0,behavior:'smooth'});render()}
function openModal(html){$('#modal').innerHTML=html;$('#modalBackdrop').classList.add('open')}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
function endDay(){state.day++;state.heat=clamp(state.heat-(state.owned.includes('crew')?5:3),0,100);refreshPrices();if(state.heat>75&&Math.random()<.28){const loss=Math.min(state.cash,Math.round(70+state.heat*3));state.cash-=loss;state.heat=clamp(state.heat-14,0,100);addEvent(`A rough day caught up with you. You paid ${money(loss)} in unexpected costs and the city’s attention eased a little.`,'bad')}if(Math.random()<.22&&state.contacts.length){const c=state.contacts[Math.floor(Math.random()*state.contacts.length)];c.status='active';addEvent(`${c.name} got in touch with a fresh opportunity.`,'good')}state.customers=state.customers.filter(()=>Math.random()>.35);render()}
function sideHustle(){const pay=90+Math.floor(Math.random()*100)+state.owned.filter(x=>['bike','car','van'].includes(x)).length*18;state.cash+=pay;state.heat=clamp(state.heat-2,0,100);if(Math.random()<.55)earnedRespect(1);addEvent(`You picked up a legit neighborhood gig and brought home ${money(pay)}. A steady win.`,'good');endDay();notify(`Side hustle paid ${money(pay)}.`)}
function layLow(){state.heat=clamp(state.heat-12,0,100);addEvent('You took a quiet day, checked in on yourself, and let the city move on.','normal');endDay();notify('A quiet day. City attention eased.')}
function findCustomers(){const count=2+Math.floor(Math.random()*2);for(let i=0;i<count;i++){const name=CUSTOMER_NAMES[Math.floor(Math.random()*CUSTOMER_NAMES.length)];const good=GOODS[Math.floor(Math.random()*GOODS.length)];state.customers.push({id:Math.random().toString(36).slice(2,9),name,good:good.id,qty:1+Math.floor(Math.random()*4),offer:Math.round(priceOf(good)*(1.12+Math.random()*.42)),icon:['🧢','🪩','🧥','🎧','🧿','🛹'][Math.floor(Math.random()*6)],note:`Looking for ${good.name}. Has ${money(Math.round(priceOf(good)*(1.12+Math.random()*.42)))} per unit.`})}state.customers=state.customers.slice(-8);state.heat=clamp(state.heat+2,0,100);earnedRespect(1);addEvent(`You worked the neighborhood and met ${count} new potential customers. Word is spreading.`,'good');endDay();go('market');notify(`${count} new faces on the market.`)}
function buyStock(gid,sid='mara',discount=0){const g=GOODS.find(x=>x.id===gid);const supplier=SUPPLIERS.find(x=>x.id===sid);const base=priceOf(g);const trust=state.suppliers[sid]||0;const unit=Math.max(5,Math.round(base*(1-discount-Math.min(.12,trust*.012))));openModal(`<div class="eyebrow">A DEAL ON THE TABLE</div><h2>${supplier.icon} ${supplier.name} has ${g.name}</h2><p>${supplier.style} Current market: <b>${money(base)}</b> each. Your ${trust}/10 trust unlocks ${Math.min(12,trust*1.2).toFixed(0)}% off.</p><div class="range-line"><label for="buyQty" style="font-size:11px">Quantity</label><input id="buyQty" type="range" min="1" max="10" value="3"><span class="range-value" id="buyQtyVal">3</span></div><div class="callout" style="margin:0"><div><strong>Deal total</strong><p id="buyTotal">3 × ${money(unit)}</p></div><strong id="buySum">${money(unit*3)}</strong></div><div class="modal-actions"><button class="btn secondary" data-close>Maybe later</button><button class="btn" id="confirmBuy">Take the deal</button></div>`);const slider=$('#buyQty');const update=()=>{$('#buyQtyVal').textContent=slider.value;$('#buyTotal').textContent=`${slider.value} × ${money(unit)}`;$('#buySum').textContent=money(unit*Number(slider.value));$('#confirmBuy').disabled=unit*Number(slider.value)>state.cash};slider.addEventListener('input',update);update();$('#confirmBuy').onclick=()=>{const qty=Number(slider.value),cost=qty*unit;if(state.cash<cost)return;state.cash-=cost;state.inventory[gid]=(state.inventory[gid]||0)+qty;state.suppliers[sid]=clamp(trust+1,0,10);addEvent(`You picked up ${qty} ${g.name} from ${supplier.name} for ${money(cost)}. The relationship feels a little warmer.`,'good');closeModal();render();notify(`${qty} units added to your inventory.`)}}
function negotiate(sid){const s=SUPPLIERS.find(x=>x.id===sid),trust=state.suppliers[sid]||0;openModal(`<div class="eyebrow">WORK THE RELATIONSHIP</div><h2>${s.icon} Talk numbers with ${s.name}</h2><p>${s.style} A respectful offer could save you money. How it lands depends on how well you know each other.</p><div class="list">${GOODS.map(g=>`<div class="row"><div class="row-icon">${g.icon}</div><div class="row-body"><div class="row-name">${g.name}</div><div class="row-desc">Market ${money(priceOf(g))} each · your trust ${trust}/10</div></div><button class="btn small" data-offer="${g.id}">Make offer</button></div>`).join('')}</div><div class="modal-actions"><button class="btn secondary" data-close>Back</button></div>`)}
function sellToCustomer(customerId){const c=state.customers.find(x=>x.id===customerId);if(!c)return;const stock=GOODS.filter(g=>(state.inventory[g.id]||0)>0);if(!stock.length){notify('No stock to sell yet. Visit the market.');return}const matched=stock.find(g=>g.id===c.good);const first=matched||stock[0];openModal(`<div class="eyebrow">A CUSTOMER IS READY</div><h2>${c.icon} ${c.name}</h2><p>${c.note} Pick a fictional good and agree on a quantity. Every deal brings a little attention.</p><label style="display:block;font-size:10px;color:var(--muted);margin-bottom:6px">YOUR GOODS</label><select id="sellGood" style="width:100%;padding:10px;border-radius:9px;background:#28292f;color:white;border:1px solid #444">${stock.map(g=>`<option value="${g.id}" ${g.id===first.id?'selected':''}>${g.icon} ${g.name} · ${state.inventory[g.id]} in stock · market ${money(priceOf(g))}</option>`).join('')}</select><div class="range-line"><label for="sellQty" style="font-size:11px">Quantity</label><input id="sellQty" type="range" min="1" max="${state.inventory[first.id]}" value="${Math.min(c.qty,state.inventory[first.id])}"><span class="range-value" id="sellQtyVal">${Math.min(c.qty,state.inventory[first.id])}</span></div><div class="callout" style="margin:0"><div><strong>Offer</strong><p id="sellHint">${money(c.offer)} per unit</p></div><strong id="sellSum">${money(c.offer*Math.min(c.qty,state.inventory[first.id]))}</strong></div><div class="modal-actions"><button class="btn secondary" data-close>Pass</button><button class="btn" id="confirmSell">Make the sale</button></div>`);const select=$('#sellGood'),slider=$('#sellQty');function sync(){const g=GOODS.find(x=>x.id===select.value),max=state.inventory[g.id];slider.max=max;if(Number(slider.value)>max)slider.value=max;const qty=Number(slider.value);const total=c.offer*qty;$('#sellQtyVal').textContent=qty;$('#sellHint').textContent=`${money(c.offer)} per unit`;$('#sellSum').textContent=money(total)}select.onchange=()=>{const g=GOODS.find(x=>x.id===select.value);slider.max=state.inventory[g.id];slider.value=Math.min(c.qty,state.inventory[g.id]);sync()};slider.oninput=sync;sync();$('#confirmSell').onclick=()=>{const g=GOODS.find(x=>x.id===select.value),qty=Number(slider.value);if(qty>state.inventory[g.id])return;const total=qty*c.offer;state.inventory[g.id]-=qty;if(!state.inventory[g.id])delete state.inventory[g.id];state.cash+=total;state.heat=clamp(state.heat+3+qty,0,100);earnedRespect(2+Math.floor(qty/2));state.customers=state.customers.filter(x=>x.id!==customerId);addEvent(`You made a ${money(total)} deal with ${c.name}, moving ${qty} ${g.name}. Your reputation grew.`,'good');closeModal();endDay();go('market');notify(`Sale complete · +${money(total)}`)}}
function buyAsset(id){const a=[...HOUSES,...GEAR].find(x=>x.id===id);if(!a||state.owned.includes(id))return;if(state.cash<a.price){notify('You need a little more cash for that.');return}openModal(`<div class="eyebrow">MAKE IT REAL</div><h2>${a.icon} ${a.name}</h2><p>${a.desc}<br><br>Purchase for <b>${money(a.price)}</b>? This will become part of your story.</p><div class="modal-actions"><button class="btn secondary" data-close>Not yet</button><button class="btn" id="confirmAsset">Make it yours</button></div>`);$('#confirmAsset').onclick=()=>{state.cash-=a.price;state.owned.push(id);if(HOUSES.some(x=>x.id===id))earnedRespect(5);addEvent(`You bought ${a.name} for ${money(a.price)}. Something solid, built by you.`,'good');closeModal();render();notify(`${a.name} added to your life.`)}}
function influence(){const cost=250+state.rep*65;if(state.cash<cost){notify('You cannot afford to make that call right now.');return}openModal(`<div class="eyebrow">A FICTIONAL CITY FAVOR</div><h2>Make a quiet call?</h2><p>A well-connected fixer can reduce the city's attention in this fictional world. It costs <b>${money(cost)}</b>, and results are never guaranteed.</p><div class="modal-actions"><button class="btn secondary" data-close>Forget it</button><button class="btn" id="confirmInfluence">Make the call · ${money(cost)}</button></div>`);$('#confirmInfluence').onclick=()=>{state.cash-=cost;const drop=16+Math.floor(Math.random()*18);state.heat=clamp(state.heat-drop,0,100);addEvent(`You spent ${money(cost)} on a discreet favor. The city's attention eased by ${drop} points.`,'normal');closeModal();render();notify('A little breathing room.') }}
function doAction(action){if(action==='work')sideHustle();if(action==='laylow')layLow();if(action==='customers')findCustomers();if(action==='influence')influence()}

