function makeOffer(sid,gid){const supplier=SUPPLIERS.find(x=>x.id===sid),good=GOODS.find(x=>x.id===gid),trust=state.suppliers[sid]||0;const lands=Math.random()<Math.min(.9,.48+trust*.045);if(lands){addEvent(`${supplier.name} accepted your offer on ${good.name}. They remember how you handled the conversation.`,'good');closeModal();buyStock(gid,sid,.12);notify('Your offer landed. Take the deal?')}else{state.suppliers[sid]=clamp(trust+1,0,10);addEvent(`${supplier.name} passed on your ${good.name} offer, but appreciated the conversation.`,'normal');closeModal();render();notify(`${supplier.name} passed this time. Trust still grew.`)}}
function quickSell(gid){const buyer=state.customers.find(c=>c.good===gid)||state.customers[0];if(!buyer){notify('No buyers yet. Work the neighborhood first.');go('market');return}sellToCustomer(buyer.id)}
function doAction(action){if(action==='work')sideHustle();if(action==='laylow')layLow();if(action==='customers')findCustomers();if(action==='influence')influence()}
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.view){go(target.dataset.view);return}if(target.dataset.go){go(target.dataset.go);return}if(target.dataset.action){doAction(target.dataset.action);return}if(target.dataset.buy){chooseSupplier(target.dataset.buy);return}if(target.dataset.sell){quickSell(target.dataset.sell);return}if(target.dataset.customer){sellToCustomer(target.dataset.customer);return}if(target.dataset.asset){buyAsset(target.dataset.asset);return}if(target.dataset.negotiate){negotiate(target.dataset.negotiate);return}if(target.dataset.offer){const supplier=$('#modal').dataset.supplier;makeOffer(supplier,target.dataset.offer);return}if(target.hasAttribute('data-close')){closeModal();return}});
