.id===select.value);slider.max=state.inventory[g.id];slider.value=Math.min(c.qty,state.inventory[g.id]);sync()};slider.oninput=sync;sync();$('#confirmSell').onclick=()=>{const g=GOODS.find(x=>x.id===select.value),qty=Number(slider.value);if(qty>state.inventory[g.id])return;const total=qty*c.offer;state.inventory[g.id]-=qty;if(!state.inventory[g.id])delete state.inventory[g.id];state.cash+=total;state.heat=clamp(state.heat+3+qty,0,100);earnedRespect(2+Math.floor(qty/2));state.customers=state.customers.filter(x=>x.id!==customerId);addEvent(`You made a ${money(total)} deal with ${c.name}, moving ${qty} ${g.name}. Your reputation grew.`,'good');closeModal();endDay();go('market');notify(`Sale complete · +${money(total)}`)}}
